    if (pageContainer) pageContainer.classList.remove("pdf-reading-mode");
    currentBookRef = null;
    totalPages = 0;

    if (typeof updateLibraryStats === "function") updateLibraryStats();
    if (typeof updateContinueReadingHero === "function") updateContinueReadingHero();
