    const popPdfFit = document.getElementById("popoverPdfFitRow");
    if (popPdfFit) {
      popPdfFit.style.display = isPdf ? "flex" : "none";
    }

    const popPdfSpread = document.getElementById("popoverPdfSpreadRow");
